using System.IO;
using System.Text.Json;
using System.Windows;
namespace WoWItemEditor;
public partial class MainWindow
{
    private async Task VerifyEquipmentLayout(CatalogResult catalog)
    {
        static void Assert(bool value,string message){if(!value)throw new InvalidOperationException(message);}
        var lookup=catalog.Items.ToDictionary(i=>i.Id);var ring=catalog.Items.First(i=>i.Slot==11);var twoHand=catalog.Items.First(i=>i.Slot==17);var shield=catalog.Items.First(i=>i.Slot==14);var head=catalog.Items.First(i=>i.Slot==1);var view=new EquipmentSetView();
        view.Bind([new("ring1",ring),new("ring2",ring),new("ring3",ring),new("twohand",twoHand),new("shield",shield)],catalog.Tooltips,lookup);
        Assert(view.Equipped[10].Key.Equals("ring1")&&view.Equipped[11].Key.Equals("ring2"),"Rings occupy separate finger slots");Assert(view.Equipped[15].Item.Id==twoHand.Id&&!view.Equipped.ContainsKey(16),"Two-handed weapon reserves both hands");Assert(view.Overflow.Count==2,"Conflicting/extra pieces remain accessible");
        var set=catalog.Tooltips.Sets[523];view.Bind(set.Members.Where(lookup.ContainsKey).Select(id=>new EquipmentViewItem(id,lookup[id])),catalog.Tooltips,lookup);Assert(view.Equipped.ContainsKey(0)&&view.Equipped.ContainsKey(4),"Dreadnaught occupies head and chest slots");view.ActivateSlot(0);var selected=view.Selection!.Item;Assert(view.TooltipText.Contains(selected.Name)&&view.TooltipText.Contains("Requires Level"),"Single selection shows the actual WoW item tooltip");int edited=0;view.EditRequested+=row=>edited=row.Item.Id;view.ActivateSlot(0,true);Assert(edited==selected.Id,"Double-click activation requests the selected item editor");view.Bind(set.Members.Where(lookup.ContainsKey).Select(id=>new EquipmentViewItem(id,lookup[id])),catalog.Tooltips,lookup);Assert(view.Selection?.Item.Id==selected.Id,"Refreshing layout retains selected item");
        int dropItem=0;view.DropRequested+=row=>dropItem=row.Item.Id;view.ActivateSlot(4);view.RequestSelectedDrops();Assert(dropItem==view.Equipped[4].Item.Id&&dropItem!=selected.Id,"Drop action follows selected set slot rather than a catalog candidate");view.ActivateSlot(0);
        var window=new Window{Title="Equipment layout verification",Content=view,Width=1260,Height=850,Background=Background,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};window.Show();await RenderEditorWindow(window,"equipment-layout-preview");window.Close();
        var created=(await ContentEditing.ListAsync()).FirstOrDefault(o=>o.Kind=="NewSet"&&o.Active&&catalog.Tooltips.Sets.ContainsKey(o.EntityId));if(created is not null){
            var timer=System.Diagnostics.Stopwatch.StartNew();var session=await CreatedSets.Load(created.EntityId);long initialMs=timer.ElapsedMilliseconds;timer.Restart();var refreshed=await CreatedSets.Load(created.EntityId,session);long refreshMs=timer.ElapsedMilliseconds;
            Assert(session.Members.All(p=>ReferenceEquals(p.Value,refreshed.Members[p.Key])),"Unchanged set refresh reuses conflict-checked member blueprints");
            int changedId=session.Members.Keys.First();var invalid=new Dictionary<int,CloneBlueprint>(session.Members){[changedId]=session.Members[changedId] with{SourceExpected=new(new())}};timer.Restart();var rechecked=await CreatedSets.Load(created.EntityId,session with{Members=invalid});long changedRefreshMs=timer.ElapsedMilliseconds;
            Assert(!ReferenceEquals(invalid[changedId],rechecked.Members[changedId])&&session.Members.Where(p=>p.Key!=changedId).All(p=>ReferenceEquals(p.Value,rechecked.Members[p.Key])),"Changed member snapshots are reloaded while other members remain cached");
            var refs=await ReferenceCatalog.LoadAsync();var isolated=catalog with{Tooltips=new TooltipData()};var merged=SetCatalogRefresh.CreatedSet(isolated,refreshed,null,refs);Assert(ReferenceEquals(merged.Originals,catalog.Originals)&&ReferenceEquals(merged.OriginalTooltips,catalog.OriginalTooltips)&&ReferenceEquals(merged.History,catalog.History),"Scoped set refresh retains baseline and history catalogs");Assert(merged.Tooltips.Sets[session.Id].Members.Order().SequenceEqual(session.Members.Keys.Order()),"Scoped set refresh updates exact set membership");Assert(session.Members.All(p=>ReferenceEquals(merged.Items.Single(i=>i.Id==p.Key),p.Value.Item.Current)),"Scoped set refresh uses saved member definitions");
            var removed=refreshed with{Members=refreshed.Members.Where(p=>p.Key!=changedId).ToDictionary()};var detached=SetCatalogRefresh.CreatedSet(merged,removed,refreshed,refs);Assert(detached.Items.Single(i=>i.Id==changedId).Number("ItemSet")==0&&!detached.Tooltips.Sets[session.Id].Members.Contains(changedId),"Scoped membership refresh preserves detached item and clears its set assignment");
            await File.WriteAllTextAsync("artifacts/set-refresh-verification.json",JsonSerializer.Serialize(new{set=session.Id,members=session.Members.Count,initialMs,refreshMs,changedRefreshMs,checks="Unchanged member reuse; changed snapshot invalidation; exact saved definitions and membership; detached item retained; original/history catalog reuse; read-only, no game writes"},new JsonSerializerOptions{WriteIndented=true}));
            var modify=new CreatedSetsWindow(catalog,refs,session){Owner=this};modify.Show();await RenderEditorWindow(modify,"modify-created-sets-preview");Assert(modify.FooterVisible,"Action buttons remain visible below equipment layout");modify.Close();}
        view.Bind([],catalog.Tooltips,lookup);Assert(view.Selection is null&&view.Equipped.Count==0,"Empty sets clear tooltip and occupied slots");
        await File.WriteAllTextAsync("artifacts/equipment-layout-verification.json",JsonSerializer.Serialize(new{checks="WoW slot positions, separate ring slots, two-hand reservation, visible overflow, selected real tooltip, double-click edit event, selection retention and empty-set clearing; no game writes"},new JsonSerializerOptions{WriteIndented=true}));
    }
}
